#pragma once

#include <span>
#include <string_view>

namespace fem::l10n::detail {

/// A catalog of the core built into the library from core/l10n/<language>.json.
struct EmbeddedCatalog {
    std::string_view language;
    std::string_view json;
};

/// The catalogs of the core, by language; defined in a source file generated by
/// cmake/EmbedCatalogs.cmake.
[[nodiscard]] std::span<const EmbeddedCatalog> core_catalogs();

}  // namespace fem::l10n::detail
